import re

def parse_frequency(frequency):
    if frequency is None or frequency.strip().lower() == "always":
        return None
    match = re.match(r'^\s*(\d+)\s*(\w+)\s*$', frequency.strip(), re.IGNORECASE)
    if not match:
        raise ValueError(f"Invalid frequency format: {frequency!r}")
    value, unit = match.groups()
    value = int(value)
    unit = unit.lower()
    kwargs = {}
    if unit in ("day", "days"):
        kwargs["days"] = value
    elif unit in ("week", "weeks"):
        kwargs["weeks"] = value
    elif unit in ("hour", "hours"):
        kwargs["hours"] = value
    elif unit in ("minute", "minutes"):
        kwargs["minutes"] = value
    elif unit in ("second", "seconds"):
        kwargs["seconds"] = value
    else:
        raise ValueError(f"Unsupported time unit: {unit!r}")
    return datetime.timedelta(**kwargs)

