import yaml

class IRValidatorException(Exception):
    pass

class IRValidator:
    REQUIRED_FIELDS = ["name", "version", "settings"]

    @classmethod
    def validate_from_file(cls, yaml_file=None):
        if yaml_file is None:
            raise IRValidatorException("No YAML file path provided.")
        if not os.path.isfile(yaml_file):
            raise IRValidatorException(f"File not found: {yaml_file}")
        with open(yaml_file, "r", encoding="utf-8") as f:
            try:
                data = yaml.safe_load(f)
            except yaml.YAMLError as e:
                raise IRValidatorException(f"Error parsing YAML: {e}")
        if not isinstance(data, dict):
            raise IRValidatorException("YAML content must be a mapping.")
        missing = [field for field in cls.REQUIRED_FIELDS if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
        return data

